import{_ as t,o as a,c as o,ae as i}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"ADR-004: Three-Mode State Machine with Shared Validation","description":"","frontmatter":{},"headers":[],"relativePath":"reference/adrs/004.md","filePath":"reference/adrs/004.md"}'),s={name:"reference/adrs/004.md"};function n(d,e,r,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="adr-004-three-mode-state-machine-with-shared-validation" tabindex="-1">ADR-004: Three-Mode State Machine with Shared Validation <a class="header-anchor" href="#adr-004-three-mode-state-machine-with-shared-validation" aria-label="Permalink to &quot;ADR-004: Three-Mode State Machine with Shared Validation&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>oh-my-codex validates ralph state via a dedicated contract (<code>ralph/contract.ts</code>) but does not have unified validation across workflow modes. omm supports three concurrent workflow modes — ralph, autopilot, and team — each with different phase sets, counters, and lifecycle rules.</p><p>Without validation, <code>omm_state_write</code> would accept arbitrary JSON, allowing invalid phase transitions, inconsistent counter values, and active workflows with terminal statuses.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>omm implements a <strong>single validation dispatcher</strong>（统一验证分发器）that routes to mode-specific validators:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>validateStateWrite(key, value)</span></span>
<span class="line"><span>  → mode = value.mode ?? key</span></span>
<span class="line"><span>  → VALIDATORS[mode] → mode-specific validation</span></span>
<span class="line"><span>  → unknown mode → pass through with timestamp only</span></span></code></pre></div><h3 id="shared-rules-across-all-modes" tabindex="-1">Shared rules across all modes <a class="header-anchor" href="#shared-rules-across-all-modes" aria-label="Permalink to &quot;Shared rules across all modes&quot;">​</a></h3><ul><li><strong>Terminal phase enforcement</strong>: phases in <code>{complete, failed, blocked}</code> require <code>active=false</code>; <code>completedAt</code> is auto-set if missing</li><li><strong>Timestamp validation</strong>: <code>startedAt</code>, <code>completedAt</code>, <code>lastUpdatedAt</code> must be valid ISO8601 when present</li><li><strong>Phase normalization</strong>: raw strings are trimmed and lowercased before validation</li><li><strong>Default injection</strong>: when <code>active=true</code> and fields are null, sensible defaults are injected (e.g., <code>iteration=0</code> for ralph)</li><li><strong>Immutability</strong>: validators work on a shallow copy (<code>{ ...candidate }</code>), never mutating the input</li></ul><h3 id="mode-specific-phase-sets" tabindex="-1">Mode-specific phase sets <a class="header-anchor" href="#mode-specific-phase-sets" aria-label="Permalink to &quot;Mode-specific phase sets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Phases</th><th>Status Field</th></tr></thead><tbody><tr><td>ralph</td><td>init, planning, executing, verifying, fixing, complete, failed</td><td><code>status</code></td></tr><tr><td>autopilot</td><td>analyzing, planning, executing, verifying, retry, complete, blocked, failed</td><td><code>status</code></td></tr><tr><td>team</td><td>planning, decomposing, executing, verifying, fixing, delegating, complete, failed</td><td><code>current_phase</code></td></tr></tbody></table><h3 id="mode-specific-counters" tabindex="-1">Mode-specific counters <a class="header-anchor" href="#mode-specific-counters" aria-label="Permalink to &quot;Mode-specific counters&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Counters (defaults)</th></tr></thead><tbody><tr><td>ralph</td><td><code>iteration</code> (0), <code>max_iterations</code> (10), <code>fix_attempt</code> (0), <code>max_fix_attempts</code> (3)</td></tr><tr><td>autopilot</td><td><code>current_step</code> (0), <code>total_steps</code> (0), <code>max_retries_per_step</code> (3)</td></tr><tr><td>team</td><td><code>fix_loop_count</code> (0), <code>max_fix_loops</code> (3)</td></tr></tbody></table><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>Single entry point for all state writes — consistent validation regardless of caller</li><li>Unknown keys pass through safely — extensible without code changes</li><li>Terminal rules prevent &quot;zombie&quot; workflows (active=true + complete status)</li><li>Default injection reduces boilerplate in SKILL.md instructions</li></ul><p><strong>Negative:</strong></p><ul><li>No workflow transition guard（缺少工作流互斥守卫）: ralph, autopilot, and team can all be <code>active=true</code> simultaneously. This is a known gap planned for Phase 1.</li><li>Shallow validation only: validators check field types and phase membership, not transition legality (e.g., jumping from <code>init</code> directly to <code>complete</code> is allowed)</li><li>Duplicated logic in MCP server: the MCP server inlines a simplified version of these validators</li></ul><p><strong>Known gap:</strong> A workflow transition reconciler (like oh-my-codex&#39;s <code>workflow-transition-reconcile.ts</code>) is needed to enforce that only one workflow mode is active at a time. See <a href="./../roadmap.html">Roadmap Phase 1</a>.</p>`,19)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
